class Solution {
public:
    int countMajoritySubarrays(vector<int>& nums, int target) {
        int ans = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int balance = 0;
            for (int j = i; j < (int)nums.size(); ++j) {
                balance += nums[j] == target ? 1 : -1;
                if (balance > 0) ++ans;
            }
        }
        return ans;
    }
};
